function addGesture(kind, text, responseTo = null, meta = {}) {
  const gesture = {
    id: uid("gesture"),
    kind,
    text: text.trim().slice(0, 600),
    responseTo: responseTo && findGesture(responseTo) ? responseTo : null,
    status: "alive",
    createdAt: nowIso(),
    meta,
  };
  state.gestures.push(gesture);
  appendReceipt(`place ${kind}`, gesture.id, gesture.text);
  persist();
  return gesture;
}

