async function importWorld(file) {
  if (!file) return;
  try {
    const parsed = JSON.parse(await file.text());
    if (
      parsed?.format === "tendora-world" &&
      parsed.seal !== checksum(JSON.stringify(parsed.world))
    ) {
      throw new Error("The portable snapshot seal does not match its contents.");
    }
    const carried = sanitizeImportedWorld(parsed?.format === "tendora-world" ? parsed.world : parsed);
    state = carried;
    const today = dayKey(new Date());
    if (!state.visits.includes(today)) state.visits.push(today);
    appendReceipt("import snapshot", state.worldId, `Carried from ${file.name.slice(0, 160)}.`);
    selectedId = null;
    replyToId = null;
    persist();
    render();
    showToast("The carried world is intact and now held here.");
  } catch (error) {
    showToast(`Import refused: ${error.message}`);
  } finally {
    elements.importFile.value = "";
  }
}

