    elements.newWorldDialog.close();
    return;
  }
  if (elements.confirmPhrase.value.trim().toLowerCase() !== "begin again") return;
  state = createFreshWorld();
  selectedId = null;
  replyToId = null;
  selectedKind = "question";
  elements.materialFilter.value = "alive";
  setSelectedKind("question");
  setReplyTarget(null);
  persist();
  elements.newWorldDialog.close();
  elements.confirmPhrase.value = "";
  elements.confirmNewWorld.disabled = true;
  switchView("material");
  render();
  showToast("A fresh surface holds the inherited laws and an open question.");
}

